// Function to compute a 3D sphere grid (10x10x10) and rotation
vec3 sphereGrid3D(vec2 fragCoord, vec2 iResolution, float time)
{
    // Base color
    vec3 color = vec3(0.0);

    // Sphere parameters
    float sphereRadius = 0.5;  // Each sphere's radius
    int   sphereCount = 10;    // 10 in each dimension
    float spacing     = 5.0;   // Distance between sphere centers

    // Normalize time to create smooth rotations within a 10-second cycle
    float t      = mod(time, 10.0) / 10.0;
    float angleX = sin(t * 3.1415926535 * 2.0) * (3.1415926535 / 2.0); // Up to 90 degrees
    float angleY = cos(t * 3.1415926535 * 2.0) * (3.1415926535 / 2.0); // Up to 90 degrees

    // Rotation matrices for rotation around X-axis and Y-axis
    mat2 rotX = mat2(cos(angleX), -sin(angleX),
                     sin(angleX),  cos(angleX));
    mat2 rotY = mat2(cos(angleY), -sin(angleY),
                     sin(angleY),  cos(angleY));

    // Convert fragCoord into a -1..1 range and apply an orthographic "zoom out"
    vec2 uv = fragCoord.xy / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y; // Correct aspect ratio
    uv *= 40.0;                            // Move "camera" further out

    // Triple nested loop for a 10x10x10 grid of spheres
    for (int i = 0; i < sphereCount; i++)
    {
        for (int j = 0; j < sphereCount; j++)
        {
            for (int k = 0; k < sphereCount; k++)
            {
                // Compute the 3D position of the current sphere
                float sphereX = (float(i) - float(sphereCount) / 2.0) * spacing;
                float sphereY = (float(j) - float(sphereCount) / 2.0) * spacing;
                float sphereZ = (float(k) - float(sphereCount) / 2.0) * spacing;

                // Create the sphere center in 3D
                vec3 sphereCenter = vec3(sphereX, sphereY, sphereZ);

                // Rotate around X-axis (affects y and z)
                sphereCenter.yz = rotX * sphereCenter.yz;

                // Rotate around Y-axis (affects x and z)
                sphereCenter.xz = rotY * sphereCenter.xz;

                // In this simple orthographic view, we'll just ignore Z when drawing
                // and measure distance in the 2D plane (uv - sphereCenter.xy).
                float dist = length(uv - sphereCenter.xy);

                // If within the radius, draw the sphere color (simple overlap)
                if (dist < sphereRadius)
                {
                    // You can modify this color or apply shading if desired
                    color = vec3(1.0, 1.0, 1.0);
                }
            }
        }
    }

    return color;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    float time = iTime; 
    // Get the final color from our 3D grid function
    vec3 color = sphereGrid3D(fragCoord, iResolution.xy, time);

    fragColor = vec4(color, 1.0);
}
